const dashboardFinanceMonthly = `-- name: DashboardFinanceMonthly :many
WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $1::uuid
      AND ($2::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $2::uuid))
),
flows AS (
    SELECT ap.currency, date_trunc('month', c.received_date)::date AS m,
           c.amount AS coll, 0::numeric AS exp, 0::numeric AS sub
    FROM project_collections c JOIN ap ON ap.id = c.project_id
    WHERE c.organization_id = $1::uuid AND c.voided_at IS NULL
      AND c.received_date >= $3::date AND c.received_date < $4::date
    UNION ALL
    SELECT ap.currency, date_trunc('month', e.expense_date)::date, 0::numeric, e.amount, 0::numeric
    FROM project_expenses e JOIN ap ON ap.id = e.project_id
    WHERE e.organization_id = $1::uuid AND e.voided_at IS NULL
      AND e.expense_date >= $3::date AND e.expense_date < $4::date
    UNION ALL
    SELECT ap.currency, date_trunc('month', sp.paid_date)::date, 0::numeric, 0::numeric, sp.amount
    FROM project_subcontractor_payments sp JOIN ap ON ap.id = sp.project_id
    WHERE sp.organization_id = $1::uuid AND sp.voided_at IS NULL
      AND sp.paid_date >= $3::date AND sp.paid_date < $4::date
    UNION ALL
    SELECT ap.currency, date_trunc('month', np.paid_date)::date, 0::numeric, 0::numeric, np.amount
    FROM subcontract_payments np JOIN ap ON ap.id = np.project_id
    WHERE np.organization_id = $1::uuid AND np.voided_at IS NULL
      AND np.paid_date >= $3::date AND np.paid_date < $4::date
)
SELECT flows.currency::text AS currency, flows.m::date AS month,
       sum(flows.coll)::numeric(18,2) AS collections,
       sum(flows.exp)::numeric(18,2) AS expenses,
       sum(flows.sub)::numeric(18,2) AS subcontract_payments
FROM flows
GROUP BY flows.currency, flows.m
ORDER BY flows.currency, flows.m
`

