const dashboardOffersByCurrency = `-- name: DashboardOffersByCurrency :many

WITH o AS (
    SELECT o.id, o.status, o.offer_date, o.current_revision_id,
           r.currency, r.grand_total, r.valid_until
    FROM offers o
    JOIN offer_revisions r ON r.id = o.current_revision_id AND r.organization_id = o.organization_id
    WHERE o.organization_id = $8::uuid AND o.is_passive = false
),
dec AS (
    SELECT o.id,
           (SELECT max(e.created_at) FROM offer_events e
            WHERE e.organization_id = $8::uuid AND e.offer_id = o.id
              AND e.revision_id = o.current_revision_id
              AND (e.event_type IN ('customer_accepted', 'customer_rejected')
                   OR (e.event_type = 'offer_updated'
                       AND COALESCE(e.metadata->>'to_status', o.status) = o.status))) AS decided_at
    FROM o
    WHERE o.status IN ($3::text, $5::text)
),
x AS (
    -- viewed_7d: teklifin EN SON görüntülenmesi son 7 günde mi? Teklif
    -- BAŞINA tek indeks araması (idx_offer_events_offer_id, ORDER BY ...
    -- LIMIT 1 ilk satırda durur): her paylaşım linki açılışı ayrı bir
    -- customer_viewed yazdığından firma geneli görüntülenme satırlarını
    -- taramak görüntülenme sayısıyla büyürdü.
    SELECT o.id, o.status, o.offer_date, o.current_revision_id, o.currency, o.grand_total, o.valid_until, dec.decided_at,
           COALESCE(lv.created_at >= $9::timestamptz, false) AS viewed_7d,
           (o.status = $3::text AND NOT EXISTS (
                SELECT 1 FROM projects p
                WHERE p.source_offer_id = o.id AND p.organization_id = $8::uuid)) AS not_converted
    FROM o
    LEFT JOIN dec ON dec.id = o.id
    LEFT JOIN LATERAL (
        SELECT e.created_at FROM offer_events e
        WHERE e.offer_id = o.id AND e.organization_id = $8::uuid
          AND e.event_type = 'customer_viewed'
        ORDER BY e.created_at DESC
        LIMIT 1
    ) lv ON true
)
SELECT x.currency::text AS currency,
       count(*)::int AS total,
       (count(*) FILTER (WHERE x.status = $1::text))::int AS draft_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.status = $1::text), 0)::numeric(18,2) AS draft_amount,
       (count(*) FILTER (WHERE x.status = $2::text))::int AS awaiting_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.status = $2::text), 0)::numeric(18,2) AS awaiting_amount,
       (count(*) FILTER (WHERE x.status = $3::text
                           AND x.decided_at >= $4::timestamptz))::int AS accepted_90d_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.status = $3::text
                           AND x.decided_at >= $4::timestamptz), 0)::numeric(18,2) AS accepted_90d_amount,
       (count(*) FILTER (WHERE x.status = $5::text
                           AND x.decided_at >= $4::timestamptz))::int AS rejected_90d_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.status = $5::text
                           AND x.decided_at >= $4::timestamptz), 0)::numeric(18,2) AS rejected_90d_amount,
       (count(*) FILTER (WHERE x.status = $2::text
                           AND x.valid_until BETWEEN $6::date AND $7::date))::int AS expiring_7d_count,
       (count(*) FILTER (WHERE x.status = $2::text AND x.valid_until < $6::date))::int AS expired_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.status = $2::text
                           AND x.valid_until < $6::date), 0)::numeric(18,2) AS expired_amount,
       (min(x.valid_until) FILTER (WHERE x.status = $2::text AND x.valid_until < $6::date))::date AS expired_oldest,
       (count(*) FILTER (WHERE x.viewed_7d))::int AS viewed_7d_count,
       (count(*) FILTER (WHERE x.not_converted))::int AS not_converted_count,
       COALESCE(sum(x.grand_total) FILTER (WHERE x.not_converted), 0)::numeric(18,2) AS not_converted_amount,
       (min((x.decided_at AT TIME ZONE 'Europe/Istanbul')::date) FILTER (WHERE x.not_converted))::date AS not_converted_oldest
FROM x
GROUP BY x.currency
ORDER BY x.currency
`

