// ============================================================ offers
// Firma geneli, arşivlenmiş (is_passive) teklifler HARİÇ; tutar ve para
// birimi güncel revizyondan. Karar tarihi offer_events'ten: müşteri
// kararı (customer_accepted/rejected) ya da iç karar (offer_updated,
// metadata.to_status = güncel durum; eski kayıtlarda metadata yoksa
// güncel durum varsayılır) -- offers.updated_at KULLANILMAZ.
func (q *Queries) DashboardOffersByCurrency(ctx context.Context, arg DashboardOffersByCurrencyParams) ([]DashboardOffersByCurrencyRow, error) {
	rows, err := q.db.Query(ctx, dashboardOffersByCurrency,
		arg.StatusDraft,
		arg.StatusSent,
		arg.StatusAccepted,
		arg.D90StartTs,
		arg.StatusRejected,
		arg.Today,
		arg.Plus6,
		arg.OrgID,
		arg.D7StartTs,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DashboardOffersByCurrencyRow
	for rows.Next() {
		var i DashboardOffersByCurrencyRow
		if err := rows.Scan(
			&i.Currency,
			&i.Total,
			&i.DraftCount,
			&i.DraftAmount,
			&i.AwaitingCount,
			&i.AwaitingAmount,
			&i.Accepted90dCount,
			&i.Accepted90dAmount,
			&i.Rejected90dCount,
			&i.Rejected90dAmount,
			&i.Expiring7dCount,
			&i.ExpiredCount,
			&i.ExpiredAmount,
			&i.ExpiredOldest,
			&i.Viewed7dCount,
			&i.NotConvertedCount,
			&i.NotConvertedAmount,
			&i.NotConvertedOldest,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

