const dashboardOperationsCounts = `-- name: DashboardOperationsCounts :one

WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $1::uuid
      AND ($5::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $5::uuid))
)
SELECT
    (SELECT count(DISTINCT m.employee_id) FROM project_members m
      JOIN ap ON ap.id = m.project_id AND ap.status = 'active'
      WHERE m.organization_id = $1::uuid
        AND (m.start_date IS NULL OR m.start_date <= $2::date)
        AND (m.end_date IS NULL OR m.end_date >= $2::date))::int AS active_crew,
    (SELECT count(*) FROM project_schedule_items si
      JOIN ap ON ap.id = si.project_id AND ap.status <> 'cancelled'
      WHERE si.organization_id = $1::uuid AND si.status IN ('planned', 'active')
        AND si.end_date BETWEEN $2::date AND $3::date)::int AS milestones_due_7d,
    (SELECT count(*) FROM project_schedule_items si
      JOIN ap ON ap.id = si.project_id AND ap.status <> 'cancelled'
      WHERE si.organization_id = $1::uuid AND si.status IN ('planned', 'active')
        AND si.end_date < $2::date)::int AS milestones_overdue,
    (SELECT min(si.end_date) FROM project_schedule_items si
      JOIN ap ON ap.id = si.project_id AND ap.status <> 'cancelled'
      WHERE si.organization_id = $1::uuid AND si.status IN ('planned', 'active')
        AND si.end_date < $2::date)::date AS milestones_overdue_oldest,
    (SELECT count(*) FROM project_photos ph
      JOIN ap ON ap.id = ph.project_id
      WHERE ph.organization_id = $1::uuid AND ph.deleted_at IS NULL
        AND ph.created_at >= $4::timestamptz)::int AS photos_7d
`

