const dashboardPlanItemsDue = `-- name: DashboardPlanItemsDue :many
WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $1::uuid
      AND ($5::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $5::uuid))
),
plan_coll AS (
    SELECT c.payment_plan_item_id, sum(c.amount) AS collected
    FROM project_collections c
    WHERE c.organization_id = $1::uuid AND c.voided_at IS NULL AND c.payment_plan_item_id IS NOT NULL
    GROUP BY c.payment_plan_item_id
)
SELECT i.id, i.project_id, i.name, ap.name AS project_name, ap.currency::text AS currency,
       (i.planned_amount - COALESCE(pc.collected, 0))::numeric(18,2) AS remaining,
       i.due_date
FROM project_payment_plan_items i
JOIN ap ON ap.id = i.project_id AND ap.status <> 'cancelled'
LEFT JOIN plan_coll pc ON pc.payment_plan_item_id = i.id
WHERE i.organization_id = $1::uuid AND i.status <> 'cancelled'
  AND i.due_date IS NOT NULL
  AND ($2::date IS NULL OR i.due_date >= $2::date)
  AND i.due_date <= $3::date
  AND i.planned_amount - COALESCE(pc.collected, 0) > 0
ORDER BY i.due_date ASC, i.id
LIMIT $4::int
`

