const dashboardProcurementCounts = `-- name: DashboardProcurementCounts :one

WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $1::uuid
      AND ($3::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $3::uuid))
),
apn AS (SELECT ap.id FROM ap WHERE ap.status <> 'cancelled'),
rq AS (
    SELECT r.status, r.due_date,
           EXISTS (SELECT 1 FROM supplier_quotations q
                   WHERE q.rfq_id = r.id AND q.organization_id = $1::uuid) AS has_quote
    FROM rfqs r
    WHERE r.organization_id = $1::uuid AND r.project_id IN (SELECT apn.id FROM apn)
      AND r.status = 'issued'
)
SELECT
    (SELECT count(*) FROM purchase_requests pr
      WHERE pr.organization_id = $1::uuid AND pr.project_id IN (SELECT apn.id FROM apn)
        AND pr.status = 'draft')::int AS pr_draft,
    (SELECT count(*) FROM purchase_requests pr
      WHERE pr.organization_id = $1::uuid AND pr.project_id IN (SELECT apn.id FROM apn)
        AND pr.status = 'submitted')::int AS pr_submitted,
    (SELECT count(*) FROM rq)::int AS rfq_issued,
    (SELECT count(*) FROM rq WHERE rq.due_date < $2::date AND rq.has_quote)::int AS rfq_awaiting_award,
    (SELECT min(rq.due_date) FROM rq WHERE rq.due_date < $2::date AND rq.has_quote)::date AS rfq_awaiting_award_oldest,
    (SELECT count(*) FROM rq WHERE rq.due_date < $2::date AND NOT rq.has_quote)::int AS rfq_past_due_no_quote,
    (SELECT min(rq.due_date) FROM rq WHERE rq.due_date < $2::date AND NOT rq.has_quote)::date AS rfq_past_due_no_quote_oldest,
    (SELECT count(*) FROM purchase_orders po
      WHERE po.organization_id = $1::uuid AND po.project_id IN (SELECT apn.id FROM apn)
        AND po.status = 'draft')::int AS po_draft,
    (SELECT count(*) FROM purchase_orders po
      WHERE po.organization_id = $1::uuid AND po.project_id IN (SELECT apn.id FROM apn)
        AND po.status = 'approved')::int AS po_approved_open,
    (SELECT count(*) FROM purchase_orders po
      WHERE po.organization_id = $1::uuid AND po.project_id IN (SELECT apn.id FROM apn)
        AND po.status = 'approved' AND po.expected_delivery_date < $2::date)::int AS po_late_delivery
`

type DashboardProcurementCountsParams struct {
	OrgID            pgtype.UUID `json:"org_id"`
	Today            pgtype.Date `json:"today"`
	RestrictToUserID pgtype.UUID `json:"restrict_to_user_id"`
}

type DashboardProcurementCountsRow struct {
	PrDraft                 int32       `json:"pr_draft"`
	PrSubmitted             int32       `json:"pr_submitted"`
	RfqIssued               int32       `json:"rfq_issued"`
	RfqAwaitingAward        int32       `json:"rfq_awaiting_award"`
	RfqAwaitingAwardOldest  pgtype.Date `json:"rfq_awaiting_award_oldest"`
	RfqPastDueNoQuote       int32       `json:"rfq_past_due_no_quote"`
	RfqPastDueNoQuoteOldest pgtype.Date `json:"rfq_past_due_no_quote_oldest"`
	PoDraft                 int32       `json:"po_draft"`
	PoApprovedOpen          int32       `json:"po_approved_open"`
	PoLateDelivery          int32       `json:"po_late_delivery"`
}

