const dashboardProjectCounts = `-- name: DashboardProjectCounts :one

WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $3::uuid
      AND ($4::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $4::uuid))
)
SELECT
    (count(*) FILTER (WHERE ap.status = 'planned'))::int   AS planned,
    (count(*) FILTER (WHERE ap.status = 'active'))::int    AS active,
    (count(*) FILTER (WHERE ap.status = 'paused'))::int    AS paused,
    (count(*) FILTER (WHERE ap.status = 'completed'))::int AS completed,
    (count(*) FILTER (WHERE ap.status = 'cancelled'))::int AS cancelled,
    count(*)::int AS total,
    (count(*) FILTER (WHERE ap.status IN ('planned', 'active', 'paused')
                        AND ap.end_date < $1::date))::int AS past_end_date,
    (count(*) FILTER (WHERE ap.status IN ('planned', 'active', 'paused')
                        AND ap.end_date BETWEEN $1::date AND $2::date))::int AS ending_within_30d
FROM ap
`

