const dashboardUpcomingPODeliveries = `-- name: DashboardUpcomingPODeliveries :many
WITH ap AS (
    SELECT p.id, p.organization_id, p.project_no, p.name, p.project_type, p.source_offer_id, p.source_revision_id, p.customer_id, p.customer_name, p.customer_phone, p.customer_email, p.customer_address, p.contract_amount, p.currency, p.status, p.start_date, p.end_date, p.description, p.internal_notes, p.created_by, p.created_at, p.updated_at FROM projects p
    WHERE p.organization_id = $1::uuid
      AND ($4::uuid IS NULL OR EXISTS (
           SELECT 1 FROM project_users pu
           WHERE pu.project_id = p.id AND pu.user_id = $4::uuid))
)
SELECT po.id, po.project_id, po.po_no, ap.name AS project_name, po.expected_delivery_date
FROM purchase_orders po
JOIN ap ON ap.id = po.project_id AND ap.status <> 'cancelled'
WHERE po.organization_id = $1::uuid AND po.status = 'approved'
  AND po.expected_delivery_date BETWEEN $2::date AND $3::date
ORDER BY po.expected_delivery_date ASC, po.id
LIMIT 8
`

