const dashboardUserCounts = `-- name: DashboardUserCounts :one

SELECT
    (count(*) FILTER (WHERE u.is_active))::int AS active,
    (count(*) FILTER (WHERE NOT u.is_active))::int AS inactive,
    (count(*) FILTER (WHERE u.is_active AND u.last_login_at IS NULL))::int AS never_logged_in,
    (count(*) FILTER (WHERE u.is_active AND r.code NOT IN ('owner', 'admin', 'legacy_user')
                        AND NOT EXISTS (SELECT 1 FROM project_users pu
                                        WHERE pu.user_id = u.id AND pu.organization_id = $1::uuid)))::int
        AS restricted_without_project,
    (count(*) FILTER (WHERE u.is_active AND NOT EXISTS (
                        SELECT 1 FROM employees e
                        WHERE e.user_id = u.id AND e.organization_id = $1::uuid)))::int AS without_employee_link
FROM users u
LEFT JOIN organization_roles r ON r.id = u.organization_role_id
WHERE u.organization_id = $1::uuid AND u.deleted_at IS NULL
`

type DashboardUserCountsRow struct {
	Active                   int32 `json:"active"`
	Inactive                 int32 `json:"inactive"`
	NeverLoggedIn            int32 `json:"never_logged_in"`
	RestrictedWithoutProject int32 `json:"restricted_without_project"`
	WithoutEmployeeLink      int32 `json:"without_employee_link"`
}

// ============================================================ users
// Silinmiş (deleted_at) kullanıcılar sayılmaz. "Projesi olmayan":
// üyelik kısıtlı bir rolde olup hiçbir project_users satırı olmayan aktif
// kullanıcılar -- hiçbir projeyi göremezler.
func (q *Queries) DashboardUserCounts(ctx context.Context, orgID pgtype.UUID) (DashboardUserCountsRow, error) {
	row := q.db.QueryRow(ctx, dashboardUserCounts, orgID)
	var i DashboardUserCountsRow
	err := row.Scan(
		&i.Active,
		&i.Inactive,
		&i.NeverLoggedIn,
		&i.RestrictedWithoutProject,
		&i.WithoutEmployeeLink,
	)
	return i, err
}

const dashboardUsersByRole = `-- name: DashboardUsersByRole :many
SELECT r.code, r.name, count(*)::int AS cnt
FROM users u
JOIN organization_roles r ON r.id = u.organization_role_id
WHERE u.organization_id = $1::uuid AND u.deleted_at IS NULL AND u.is_active
GROUP BY r.code, r.name
ORDER BY (CASE r.code WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 WHEN 'project_manager' THEN 2
                      WHEN 'finance' THEN 3 WHEN 'field' THEN 4 WHEN 'legacy_user' THEN 5 ELSE 6 END),
         r.name
`

type DashboardUsersByRoleRow struct {
	Code string `json:"code"`
	Name string `json:"name"`
	Cnt  int32  `json:"cnt"`
}

func (q *Queries) DashboardUsersByRole(ctx context.Context, orgID pgtype.UUID) ([]DashboardUsersByRoleRow, error) {
	rows, err := q.db.Query(ctx, dashboardUsersByRole, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DashboardUsersByRoleRow
	for rows.Next() {
		var i DashboardUsersByRoleRow
		if err := rows.Scan(&i.Code, &i.Name, &i.Cnt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const dashboardUsersWithOverrides = `-- name: DashboardUsersWithOverrides :one
SELECT count(DISTINCT o.user_id)::int AS users
FROM user_permission_overrides o
JOIN users u ON u.id = o.user_id
WHERE o.organization_id = $1::uuid AND u.organization_id = $1::uuid
  AND u.deleted_at IS NULL AND u.is_active
`

func (q *Queries) DashboardUsersWithOverrides(ctx context.Context, orgID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, dashboardUsersWithOverrides, orgID)
	var users int32
	err := row.Scan(&users)
	return users, err
}

